import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { Layout, theme } from '@atlantis/shared';
import type { NavEntry, NavigationConfig } from '@atlantis/shared';
import { Sidebar } from './components/Sidebar';
import { MarkdownViewer } from './components/MarkdownViewer';
import navigation from './navigation.json';
import styled from '@emotion/styled';

const config = navigation as NavigationConfig;

function findEntry(entries: NavEntry[], id: string): NavEntry | undefined {
  for (const entry of entries) {
    if (entry.id === id) return entry;
    if (entry.children) {
      const found = findEntry(entry.children, id);
      if (found) return found;
    }
  }
  return undefined;
}

function flattenLeaves(entries: NavEntry[]): NavEntry[] {
  return entries.flatMap((e) =>
    e.children ? flattenLeaves(e.children) : e.file ? [e] : [],
  );
}

function getEntryFromHash(hash: string, entries: NavEntry[]): NavEntry | undefined {
  const match = hash.match(/^#\/docs\/(.+)$/);
  if (match) return findEntry(entries, match[1]);
  return undefined;
}

const WelcomeScreen = styled.div`
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
  color: ${theme.colors.mainTextMuted};
  font-family: ${theme.typography.fontFamily};
  font-size: ${theme.typography.fontSizeMd};
`;

interface AppProps {
  topBarRight?: React.ReactNode;
}

export default function App({ topBarRight }: AppProps) {
  const leaves = useMemo(() => flattenLeaves(config.entries), []);

  const [activeEntry, setActiveEntry] = useState<NavEntry | null>(() => {
    const fromHash = getEntryFromHash(window.location.hash, config.entries);
    return fromHash ?? leaves[0] ?? null;
  });

  useEffect(() => {
    const onHashChange = () => {
      const entry = getEntryFromHash(window.location.hash, config.entries);
      if (entry) setActiveEntry(entry);
    };
    window.addEventListener('hashchange', onHashChange);
    return () => window.removeEventListener('hashchange', onHashChange);
  }, []);

  useEffect(() => {
    if (activeEntry && !window.location.hash.includes('/blog/')) {
      window.location.hash = `#/blog/${activeEntry.id}`;
    }
  }, []);

  const handleSelect = useCallback(
    (entry: NavEntry) => {
      if (!entry.file) return;
      setActiveEntry(entry);
      window.location.hash = `#/blog/${entry.id}`;
    },
    [],
  );

  const currentIndex = leaves.findIndex((e) => e.id === activeEntry?.id);
  const prevEntry = currentIndex > 0 ? leaves[currentIndex - 1] : null;
  const nextEntry = currentIndex < leaves.length - 1 ? leaves[currentIndex + 1] : null;

  const pageTitle = activeEntry?.label ?? activeEntry?.name ?? 'Atlantis';

  return (
    <Layout
      title={pageTitle}
      activeId={activeEntry?.id ?? null}
      topBarRight={topBarRight}
      sidebar={
        <Sidebar config={config} activeId={activeEntry?.id ?? null} onSelect={handleSelect} />
      }
    >
      {activeEntry?.file ? (
        <MarkdownViewer
          file={activeEntry.file}
          prevEntry={prevEntry}
          nextEntry={nextEntry}
          onNavigate={handleSelect}
        />
      ) : (
        <WelcomeScreen>Select a page from the sidebar</WelcomeScreen>
      )}
    </Layout>
  );
}
